-- Módulo 39: paradas de mantenimiento preventivo programadas para los centros de trabajo (módulo 33).
CREATE TABLE "MantenimientosPreventivos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Numero" character varying(20) NOT NULL,
    "CentroTrabajoId" integer NOT NULL,
    "Descripcion" character varying(250) NOT NULL,
    "FechaProgramada" date NOT NULL,
    "DuracionHorasPlanificada" numeric(5, 2) NOT NULL,
    "FrecuenciaDias" integer,
    "Responsable" character varying(100),
    "Estado" character varying(12) NOT NULL,
    "FechaInicioReal" timestamp with time zone,
    "FechaFinReal" timestamp with time zone,
    "HorasReales" numeric(5, 2),
    "Observaciones" character varying(500),
    "MotivoCancelacion" character varying(250),
    CONSTRAINT "PK_MantenimientosPreventivos" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_MantenimientosPreventivos_CentrosTrabajo_CentroTrabajoId"
        FOREIGN KEY ("CentroTrabajoId") REFERENCES "CentrosTrabajo" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_MantenimientosPreventivos_Duracion"
        CHECK ("DuracionHorasPlanificada" > 0 AND "DuracionHorasPlanificada" <= 168),
    CONSTRAINT "CK_MantenimientosPreventivos_Frecuencia"
        CHECK ("FrecuenciaDias" IS NULL OR "FrecuenciaDias" BETWEEN 1 AND 3650),
    CONSTRAINT "CK_MantenimientosPreventivos_HorasReales"
        CHECK ("HorasReales" IS NULL OR ("HorasReales" > 0 AND "HorasReales" <= 168)),
    CONSTRAINT "CK_MantenimientosPreventivos_Estado"
        CHECK ("Estado" IN ('Programado', 'EnEjecucion', 'Completado', 'Cancelado'))
);

CREATE UNIQUE INDEX "IX_MantenimientosPreventivos_Numero"
    ON "MantenimientosPreventivos" ("Numero");
CREATE INDEX "IX_MantenimientosPreventivos_CentroTrabajoId"
    ON "MantenimientosPreventivos" ("CentroTrabajoId");
CREATE INDEX "IX_MantenimientosPreventivos_FechaProgramada"
    ON "MantenimientosPreventivos" ("FechaProgramada");
CREATE INDEX "IX_MantenimientosPreventivos_Estado"
    ON "MantenimientosPreventivos" ("Estado");
-- Un centro no tiene dos paradas no canceladas el mismo día.
CREATE UNIQUE INDEX "IX_MantenimientosPreventivos_CentroTrabajoId_FechaProgramada"
    ON "MantenimientosPreventivos" ("CentroTrabajoId", "FechaProgramada") WHERE "Estado" <> 'Cancelado';
